                if (panel) { panel.style.display = (!finished && (i + 1) === cur) ? 'block' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = finished ? 'none' : 'flex'; }
            var idx = Math.min(cur, this.ROUNDS.length) - 1;
            var nameEl = document.getElementById('roundName');
            if (nameEl) { nameEl.textContent = finished ? this._t('round_done') : this._t(this.ROUNDS[idx].nameKey); }
            var briefEl = document.getElementById('briefingText');
            if (briefEl) { briefEl.innerHTML = finished ? this._t('brief_done') : this._t(this.ROUNDS[idx].briefKey); }
            this._renderDynamic(state);
        }

        _renderDynamic(state) {
            var ds = (state && state.domainState) || {};
            var ss = ds.seasons || [];
            var rounds = ds.rounds || [];
            var sEl = document.getElementById('seasonText');
            if (sEl) { sEl.innerHTML = ss.length ? this._seasonHtml(ds, ss[ss.length - 1]) : this._t('sem_pending'); }
            var fbEl = document.getElementById('feedbackText');
            if (fbEl) {
                fbEl.classList.remove('ck2187-warn');
                var last = rounds.length ? rounds[rounds.length - 1] : null;
                if (!last) { fbEl.innerHTML = this._t('feedback_empty'); }
                else {
                    fbEl.innerHTML = this._feedbackHtml(ds, last);
                    if (last.verdictKey !== 'ok') { fbEl.classList.add('ck2187-warn'); }
                }
            }
        }

        _seasonHtml(ds, s) {
            var v = {
                river: String(s.river), deliv: this._fmt1(s.D), wo: this._pct(s.wO), ws: this._pct(s.wS),
                fallow: String(s.fallow), orch: this._pct(s.k), vm: this._fmtM(s.vm), small: this._fmtM(s.mS),
                res: this._fmtM(s.reserve), comp: this._fmtM(s.comp), loss: this._pct(s.loss), theft: this._pct(s.theft),
                interest: this._fmtM(s.interest)
            };
            var html = this._t('sem_body', v);
            if (s.comp > 0) { html += '<span class="ck2187-reveal">' + this._t('s_comp', v) + '</span>'; }
            if (s.loss > 0) { html += '<span class="ck2187-reveal">' + this._t('s_trees', v) + '</span>'; }
            if (s.ecocut > 0) { html += '<span class="ck2187-reveal">' + this._t('s_eco') + '</span>'; }
            if (s.swap) { html += '<span class="ck2187-reveal">' + this._t('s_swap') + '</span>'; }
            if (s.interest > 0) { html += '<span class="ck2187-reveal">' + this._t('s_interest', v) + '</span>'; }
            if (ds.capKey) { html += '<span class="ck2187-reveal">' + this._t(ds.capKey) + '</span>'; }
            return html;
        }

        _feedbackHtml(ds, r) {
            var v = { pts: String(Math.round(r.pts * 10) / 10) };
            var html = '<strong>' + this._t('fb_points', v) + '</strong> ' + this._t('fb_r' + r.period + '_' + r.verdictKey, v);
            if (r.period === 4 && ds.position !== null && ds.position !== undefined) {
                html += ' ' + this._t('pos_line', { pos: this._fmtM(ds.position) });
            }
            return html;
        }

        _readSelect(id, allowed) {
            var el = document.getElementById(id);
            if (!el) { return null; }
            var val = String(el.value);
            if (allowed.indexOf(val) === -1) { return null; }
            return val;
        }

        validateDecisions(decisions) {
            var sim = window.mySimulation;
            var state = sim && sim.state ? sim.state : { currentPeriod: 1, history: [] };
            var period = state.currentPeriod || 1;
            var done = state.history ? state.history.length : 0;
            var warn = function(key) {
                sim.uiManager.showNotification(sim.t(key), 'warning');
                return false;
            };
            if (done >= this.ROUNDS.length || period > this.ROUNDS.length) { return warn('warn_finished'); }
            if (period === 1) {
                var tariff1 = this._readSelect('r1_tariff', TARIFFS);
                var canal1 = this._readSelect('r1_canal', CANALS);
                var proto1 = this._readSelect('r1_proto', PROTOS);
                if (!tariff1 || !canal1 || !proto1) { return warn('warn_r1'); }
                decisions.round1 = { tariff: tariff1, canal: canal1, proto: proto1 };
                return true;
            }
            if (period === 2) {
                var rule2 = this._readSelect('r2_rule', RULES);
                var prio2 = this._readSelect('r2_prio', PRIOS);
                var enf2 = this._readSelect('r2_enf', ENFS);
                if (!rule2 || !prio2 || !enf2) { return warn('warn_r2'); }
                decisions.round2 = { rule: rule2, prio: prio2, enf: enf2 };
                return true;
            }
            if (period === 3) {
                var rule3 = this._readSelect('r3_rule', RULES);
                var inv3 = this._readSelect('r3_inv', INVS);
                var prio3 = this._readSelect('r3_prio', PRIOS);
                if (!rule3 || !inv3 || !prio3) { return warn('warn_r3'); }
                decisions.round3 = { rule: rule3, inv: inv3, prio: prio3 };
                return true;
            }
            if (period === 4) {
                var rule4 = this._readSelect('r4_rule', RULES);
                var stat4 = this._readSelect('r4_stat', STATS);
                var tar4 = this._readSelect('r4_tar', TARS);
                if (!rule4 || !stat4 || !tar4) { return warn('warn_r4'); }
                decisions.round4 = { rule: rule4, stat: stat4, tar: tar4 };
                return true;
            }
            return warn('warn_finished');
        }

        calculateResults(state) {
            var out = this._computeRound(state);
            var self = this;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state); }, 400);
            return out;
        }

        // Round model. Every carried quantity is rebuilt from the decision history, so a resubmit is idempotent.
        _computeRound(state) {
            var ds = state.domainState;
            var raw = state.decisions || {};
            var period = state.currentPeriod || 1;
            var saved = ds.dec || {};
            var d = {};
            var k;
            for (k = 1; k <= period; k++) {
                if (raw['round' + k]) { d['round' + k] = raw['round' + k]; }
                else if (k < period && saved['round' + k]) { d['round' + k] = saved['round' + k]; }
            }
            ds.dec = JSON.parse(JSON.stringify(d));
            var rounds = [];
            var seasons = [];
            var reserve = C.RESERVE0;
            var minReserve = C.RESERVE0;
            var orchardK = 1;
            var ecoCut = 0;
            var gapMax = 0;
            var pos = null;
            var r, known, s, rub, outp, interest, gap, vmp, shp;
            for (r = 1; r <= period; r++) {
                known = this._known(d, r);
                s = this._season(known, r, orchardK);
                orchardK = Math.max(0, orchardK - s.loss);
                interest = reserve < 0 ? C.INTEREST * (-reserve) : 0;
                reserve = reserve + s.rev - s.cost - s.capex - interest;
                s.interest = interest;
                s.reserve = reserve;
                s.k = orchardK;
                minReserve = Math.min(minReserve, reserve);
                ecoCut += s.ecocut;
                gap = Math.max(0, (s.wO - s.wS) * 100 - C.SOC_FREE);
                gapMax = Math.max(gapMax, gap);
                seasons.push(s);
                rub = this._rubric(known, r);
                vmp = this._clamp01(s.vm / C.VM_FULL);
                shp = this._clamp01(s.mS / C.SH_FULL);
                if (r < 4) {
                    outp = 5 * vmp + 3 * shp + 3 * this._clamp01((reserve - C.RES_LO) / (C.RES_HI - C.RES_LO));
                } else {
                    pos = this._position(known, reserve);
                    outp = 3 * vmp + 2 * shp + 6 * this._clamp01((pos - C.POS_LO) / (C.POS_HI - C.POS_LO));
                }
                rounds.push({ period: r, rub: rub, outp: outp, pts: rub + outp, verdictKey: this._verdict(known, r, minReserve) });
            }
            var last = seasons[seasons.length - 1];
            ds.rounds = rounds;
            ds.seasons = seasons;
            ds.reserve = reserve;
            ds.minReserve = minReserve;
            ds.orchardK = orchardK;
            ds.ecoCut = ecoCut;
            ds.gapMax = gapMax;
            ds.position = pos;
            var score = this._composite(ds);
            ds.capKey = this._capKey(ds);
            ds.performance = { overallScore: score };
            ds.performanceTier = this._tier(score);
            ds.scoreHistory = (ds.scoreHistory || []).slice(0, period - 1);
            ds.scoreHistory[period - 1] = score;
            ds.scoreHistory.length = period;
            return {
                period: period,
                roundPoints: Math.round(rounds[period - 1].pts * 10) / 10,
                valleyMargin: last.vm,
                smallIncome: last.mS,
                reserve: reserve,
                delivered: Math.round(last.D * 10) / 10,
                waterSmall: Math.round(last.wS * 100),
                score: score,
                overallScore: score
            };
        }

        _known(d, r) {
            var out = {};
            var k;
            for (k = 1; k <= r; k++) { if (d['round' + k]) { out['round' + k] = d['round' + k]; } }
            return out;
        }

        _clamp01(x) {
            return Math.max(0, Math.min(1, x));
        }

        _season(dec, q, kPrev) {
            var r1 = dec.round1;
            var r2 = (q >= 2) ? dec.round2 : null;
            var r3 = (q >= 3) ? dec.round3 : null;
            var r4 = (q >= 4) ? dec.round4 : null;
            var river = C.RIVER[q - 1];
            var prio = (q === 2) ? r2.prio : ((q === 3) ? r3.prio : 'full');
            var ecocut = (prio === 'cut') ? C.ECO_CUT : 0;
            var swap = (prio === 'swap');
            var canal = river - C.TOWN - (C.ECO - ecocut) + (swap ? C.SWAP : 0);
            var lined = (r1.canal === 'own' && q >= 2) || (r1.canal === 'fund' && q >= 3);
            var eff = lined ? C.EFF_LINED : C.EFF0;
            var enf = r2 ? r2.enf : 'none';
            var theft = C.THEFT[enf][q - 1];
            var res = !!(r3 && r3.inv === 'res');
            var D = canal * eff * (1 - theft) + (res ? C.RES_HM3 : 0);
            var tec = !!(r3 && r3.inv === 'tec' && q >= 4);
            var reqO = tec ? C.REQ_O * (1 - C.TEC_CUT) : C.REQ_O;
            var demO = C.HA_O * kPrev * reqO;
            var rule = 'prorrata';
            if (q === 2) { rule = r2.rule; }
            if (q === 3) { rule = r3.rule; }
            if (q === 4) { rule = r4.rule; }
            var terms = C.FALLOW[r1.proto === 'pre' ? 'pre' : 'crisis'];
            var fallowHa = 0;
            var rate = 0;
            if (rule === 'fallow') {
                fallowHa = (q === 3) ? C.FALLOW3 : terms[0];
                rate = terms[1];
            }
            var plantedS = C.HA_S - fallowHa;
            var demS = plantedS * C.REQ_S;
            var wO, wS, w;
            if (rule === 'priority') {
                wO = Math.min(1, D / demO);
                wS = Math.min(1, Math.max(0, D - demO * wO) / demS);
            } else {
                w = Math.min(1, D / (demO + demS));
                wO = w;
                wS = w;
            }
            var fO = Math.max(0, 1 - C.SLOPE_O * (1 - wO));
            var fS = Math.max(C.FLOOR_S, 1 - C.SLOPE_S * (1 - wS));
            var loss = C.DAMAGE_K * Math.max(0, C.DAMAGE_W - wO);
            var comp = fallowHa * rate;
            var mO = C.HA_O * kPrev * C.REV_O * fO - C.HA_O * C.COST_O - comp;
            var mS = plantedS * (C.REV_S * fS - C.COST_S) + comp;
            var hit = (r1.proto === 'council' && q >= 2) ? C.COUNCIL_HIT : 0;
            var rev;
            if (q <= 3 || r4.tar === 'keep') {
                rev = C.TARIFF[r1.tariff] * D / 1000 * (C.COLLECT[r1.tariff] - hit);
            } else if (r4.tar === 'cut') {
                rev = C.TARIFF.t20 * D / 1000 * (C.COLLECT.t20 - hit);
            } else {
                rev = (C.TWO_FIXED + C.TWO_VOL * D / 1000) * C.TWO_COLLECT;
            }
            var cost = C.OM;
            if (enf === 'guards' && q >= 2) { cost += C.GUARD_COST; }
            if (enf === 'telem' && q >= 2) { cost += C.TELEM_OM; }
            if (swap) { cost += C.SWAP_COST; }
            var capex = 0;
            if (q === 1) {
                if (r1.canal === 'own') { capex += C.LINE_CAPEX; }
                if (r1.canal === 'fund') { capex += C.FUND_FEE; }
                if (r1.proto === 'pre') { capex += C.PROTO_ADMIN; }
            }
            if (q === 2 && enf === 'telem') { capex += C.TELEM_CAPEX; }
            if (q === 3) {
                if (r1.canal === 'fund') { capex += C.FUND_SHARE; }
                if (r3.inv === 'res') { capex += C.RES_CAPEX; }
                if (r3.inv === 'tec') { capex += C.TEC_CAPEX; }
            }
            return {
                q: q, river: river, D: D, eff: eff, theft: theft, wO: wO, wS: wS, loss: loss, fallow: fallowHa, comp: comp,
                mO: mO, mS: mS, vm: mO + mS, rev: rev, cost: cost, capex: capex, ecocut: ecocut, swap: swap, rule: rule
            };
        }

        _rubric(dec, r) {
            var P = C.PTS;
            if (r === 1) { return P.tariff1[dec.round1.tariff] + P.canal1[dec.round1.canal] + P.proto1[dec.round1.proto]; }
            if (r === 2) { return P.rule2[dec.round2.rule] + P.prio2[dec.round2.prio] + P.enf2[dec.round2.enf]; }
            if (r === 3) { return P.rule3[dec.round3.rule] + P.inv3[dec.round3.inv] + P.prio3[dec.round3.prio]; }
            return P.rule4[dec.round4.rule] + P.stat4[dec.round4.stat] + P.tar4[dec.round4.tar];
        }

        _position(dec, reserve) {
            var p = reserve;
            var r1 = dec.round1, r2 = dec.round2, r3 = dec.round3;
            if (r1.canal === 'own') { p += C.LINE_CAPEX * C.RESID.lined; }
            if (r1.canal === 'fund') { p += C.FUND_SHARE * C.RESID.lined; }
            if (r3.inv === 'res') { p += C.RES_CAPEX * C.RESID.res; }
            if (r2.enf === 'telem') { p += C.TELEM_CAPEX * C.RESID.telem; }
            return p;
        }

        _verdict(dec, r, minReserve) {
            if (r === 1) {
                var r1 = dec.round1;
                if (r1.proto !== 'pre') { return 'noproto'; }
                if (r1.tariff !== 't30') { return 'tariff'; }
                if (r1.canal === 'none') { return 'nocanal'; }
                return 'ok';
            }
            if (r === 2) {
                var r2 = dec.round2;
                if (r2.prio === 'cut') { return 'eco'; }
                if (r2.rule === 'priority') { return 'grab'; }
                if (r2.rule === 'prorrata') { return 'even'; }
                if (r2.enf === 'none') { return 'leak'; }
                return 'ok';
            }
            if (r === 3) {
                var r3 = dec.round3;
                if (r3.prio === 'cut') { return 'eco'; }
                if (r3.rule === 'priority') { return 'grab'; }
                if (r3.inv === 'none') { return 'stop'; }
                return 'ok';
            }
            var r4 = dec.round4;
            if (minReserve < -C.LINE) { return 'squeeze'; }
            if (r4.stat !== 'fallow') { return 'nostatute'; }
            if (r4.rule === 'fallow') { return 'paidrain'; }
            if (r4.tar === 'cut') { return 'populist'; }
            return 'ok';
        }

        _tier(score) {
            if (score >= 75) { return 'excellent'; }
            if (score >= 55) { return 'good'; }
            return 'beginner';
        }

        _ecoCap(ds) {
            return Math.max(C.CAP_FLOOR, C.ECO_CAP - C.ECO_K * ((ds && ds.ecoCut) || 0));
        }

        _socCap(ds) {
            return Math.max(C.CAP_FLOOR, C.SOC_CAP - C.SOC_K * ((ds && ds.gapMax) || 0));
        }

        _liqCap(ds) {
            var mr = (ds && typeof ds.minReserve === 'number') ? ds.minReserve : C.RESERVE0;
            return Math.max(C.CAP_FLOOR, C.LIQ_CAP - C.LIQ_K * (-mr - C.LINE));
        }

        _cap(ds) {
            var cap = 100;
            var mr = (ds && typeof ds.minReserve === 'number') ? ds.minReserve : C.RESERVE0;
            if (((ds && ds.ecoCut) || 0) > 0) { cap = Math.min(cap, this._ecoCap(ds)); }
            if (((ds && ds.gapMax) || 0) > 0) { cap = Math.min(cap, this._socCap(ds)); }
            if (mr < -C.LINE) { cap = Math.min(cap, this._liqCap(ds)); }
            return cap;
        }

        _total(ds) {
            var rounds = (ds && ds.rounds) || [];
            var total = 0;
            var i;
            for (i = 0; i < rounds.length; i++) { total += rounds[i].pts; }
            return total;
        }

        _capKey(ds) {
            var total = this._total(ds);
            var cap = this._cap(ds);
            if (total <= cap) { return null; }
            if (((ds && ds.ecoCut) || 0) > 0 && cap === this._ecoCap(ds)) { return 'cap_eco'; }
            if (((ds && ds.gapMax) || 0) > 0 && cap === this._socCap(ds)) { return 'cap_social'; }
            return 'cap_liq';
        }

        _composite(ds) {
            var total = Math.min(this._cap(ds), this._total(ds));
            return Math.max(0, Math.min(100, Math.round(total)));
        }

        setupUI(uiManager) {
            var self = this;
            var lastS = function(ds) { var ss = (ds && ds.seasons) || []; return ss.length ? ss[ss.length - 1] : null; };
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.performance.overallScore', function(v) { return (typeof v === 'number') ? String(v) : '0'; });
            uiManager.bind('vmDisplay', 'domainState', function(ds) { var s = lastS(ds); return s ? self._fmtM(s.vm) : '—'; });
            uiManager.bind('smallDisplay', 'domainState', function(ds) { var s = lastS(ds); return s ? self._fmtM(s.mS) : '—'; });
            uiManager.bind('reserveDisplay', 'domainState', function(ds) { return self._fmtM((ds && typeof ds.reserve === 'number') ? ds.reserve : C.RESERVE0); });
            uiManager.bind('delivDisplay', 'domainState', function(ds) { var s = lastS(ds); return s ? self._fmt1(s.D) : '—'; });
            uiManager.bind('woDisplay', 'domainState', function(ds) { var s = lastS(ds); return s ? self._pct(s.wO) : '—'; });
            uiManager.bind('wsDisplay', 'domainState', function(ds) { var s = lastS(ds); return s ? self._pct(s.wS) : '—'; });
            uiManager.bind('orchDisplay', 'domainState', function(ds) { return self._pct((ds && typeof ds.orchardK === 'number') ? ds.orchardK : 1); });
        }

        getChartConfig() {
            var t = this._t.bind(this);
            var sp = t('s_short');
            return {
                marginChart: {
                    type: 'bar',
                    data: {
                        labels: [sp + '1', sp + '2', sp + '3', sp + '4'],
                        datasets: [{ label: t('chart_dataset'), data: [0, 0, 0, 0], backgroundColor: ['#2f6f8f', '#a0522d', '#4f7d3a', '#1f5a7a'], borderWidth: 0 }]
                    },
                    options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { y: { ticks: { color: '#2b3a40' } }, x: { ticks: { color: '#2b3a40' } } } }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var ss = ds.seasons || [];
            var hist = ds.scoreHistory || [];
            var data = [0, 0, 0, 0];
            var sp = this._t('s_short');
            var i;
            for (i = 0; i < ss.length && i < 4; i++) { data[i] = Math.round(ss[i].vm * 10) / 10; }
            return {
                marginChart: {
                    labels: [sp + '1', sp + '2', sp + '3', sp + '4'],
                    datasets: [{ data: data, label: this._t('chart_dataset') + (hist.length ? ' · ' + sp + hist.length : '') }]
                }
            };
        }

        getHistoryTableConfig() {
            var self = this;
            return [
                { key: 'results.roundPoints', label: 'Points', i18nKey: 'col_points' },
                { key: 'results.valleyMargin', label: 'Valley margin', i18nKey: 'col_vm', formatter: function(v) { return self._fmtM(v); } },
                { key: 'results.smallIncome', label: 'Smallholder income', i18nKey: 'col_small', formatter: function(v) { return self._fmtM(v); } },
                { key: 'results.reserve', label: 'Junta cash', i18nKey: 'col_res', formatter: function(v) { return self._fmtM(v); } },
                { key: 'results.delivered', label: 'Water delivered (hm3)', i18nKey: 'col_deliv' },
                { key: 'results.waterSmall', label: 'Water met, smallholders (%)', i18nKey: 'col_ws' },
                { key: 'results.score', label: 'Score', i18nKey: 'col_score' }
            ];
        }

        getHint(state, results) {
            var ds = state.domainState || {};
            var r = (ds.rounds || [])[(results.period || 1) - 1];
            if (!r) { return null; }
            return this._t('hint_r' + r.period + '_' + r.verdictKey);
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) { return {}; }
            var ds = window.mySimulation.state.domainState;
            var ss = ds.seasons || [];
            var hist = ds.scoreHistory || [];
            var dec = ds.dec || {};
            var composite = this._composite(ds);
            var performance = 'Beginner';
            if (composite >= 55) { performance = 'Good'; }
            if (composite >= 75) { performance = 'Excellent'; }
            var vmSum = 0, smallSum = 0, i;
            for (i = 0; i < ss.length; i++) { vmSum += ss[i].vm; smallSum += ss[i].mS; }
            var insights = [];
            var r1 = dec.round1 || {};
            var r2 = dec.round2 || {};
            var r3 = dec.round3 || {};
            var r4 = dec.round4 || {};
            insights.push((r2.rule === 'priority' || r3.rule === 'priority') ? this._t('insight_rule_grab') : ((r2.rule === 'prorrata') ? this._t('insight_rule_even') : this._t('insight_rule_ok')));
            insights.push((r1.canal === 'none' && r2.enf === 'none' && r3.inv === 'none') ? this._t('insight_eff_none') : this._t('insight_eff_ok'));
            insights.push((ds.ecoCut || 0) > 0 ? this._t('insight_eco_cut') : this._t('insight_eco_ok'));
            insights.push((r4.stat === 'fallow' && r4.tar === 'two') ? this._t('insight_inst_ok') : this._t('insight_inst_gap'));
            insights.push(this._t('insight_next'));
            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                reserve: ds.reserve,
                minReserve: ds.minReserve,
                position: ds.position,
                valleyMargin: vmSum,
                smallIncome: smallSum,
                orchardK: ds.orchardK,
                rounds: hist.length,
                performance: performance,
                performanceKey: performance.toLowerCase(),
                performanceLabel: this._cl('grade_' + performance.toLowerCase(), performance),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var items = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            return '<div class="ck2187-cm">'
                + '<div class="ck2187-cm-score">' + score + '<span class="ck2187-cm-max">/100</span></div>'
                + '<div class="ck2187-cm-verdict">' + (s.performanceLabel || s.performance || '') + '</div>'
                + '<div class="ck2187-cm-kpis">'
                + '<div class="ck2187-cm-kpi">' + this._t('cm_kpi_vm') + '<strong>' + this._fmtM(s.valleyMargin) + '</strong></div>'
                + '<div class="ck2187-cm-kpi">' + this._t('cm_kpi_small') + '<strong>' + this._fmtM(s.smallIncome) + '</strong></div>'
                + '<div class="ck2187-cm-kpi">' + this._t('cm_kpi_pos') + '<strong>' + (s.position === null || s.position === undefined ? '—' : this._fmtM(s.position)) + '</strong></div>'
                + '<div class="ck2187-cm-kpi">' + this._t('cm_kpi_orch') + '<strong>' + this._pct(s.orchardK) + '</strong></div>'
                + '</div>'
                + '<div class="ck2187-cm-debrief">' + this._t('cm_debrief') + '</div>'
                + '<ul class="ck2187-cm-insights">' + items + '</ul>'
                + '</div>';
        }

